from __future__ import annotations
import base64
import gzip
import json
from pathlib import Path

PAYLOADS = {'public/content/modules/compilers-metaprogramming.json': '', 'src/test/content/compilersMetaprogrammingContent.test.ts': '', 'src/test/integration/expertCompilersProject.integration.test.ts': ''}

for target, encoded in PAYLOADS.items():
    path = Path(target)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(encoded)))

index_path = Path("public/content/module-packages.json")
index = json.loads(index_path.read_text(encoding="utf-8"))
entry = "/content/modules/compilers-metaprogramming.json"
after = "/content/modules/parallelism-systems.json"
files = index["files"]
if entry not in files:
    files.insert(files.index(after) + 1, entry)
index_path.write_text(json.dumps(index, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

Path("scripts/materialize_expert_compilers.py").unlink(missing_ok=True)
Path(".github/workflows/materialize-expert-compilers.yml").unlink(missing_ok=True)
